import * as THREE from './vendor/three.module.js';
import {FEMALE_HERO_BODY} from './female-hero-body.js?v=rainbow-solara-body-280';
import {SolaraCharacter} from './solara-character.js?v=rainbow-full-solara-290';
import {styleRainbowStar} from './rainbow-star-style.js?v=rainbow-full-solara-290';
export const SPECTRUM=['#ff4764','#ff983d','#ffe35b','#62ed81','#44d9ff','#5980ff','#c070ff'];
const Y=new THREE.Vector3(0,1,0);
export class PrismwingCharacter {
 constructor(root,model,appearanceModel,appearanceSpec){this.root=root;this.base=new SolaraCharacter(root,model,appearanceModel,appearanceSpec,{variant:'prism'});this.character=this.base.character;styleRainbowStar(this.base);this.styleScale=FEMALE_HERO_BODY.height/2.4;this.wings=[];this.feathers=[];this.tails=[];this.box=new THREE.BoxGeometry(1,1,1);this.ball=new THREE.IcosahedronGeometry(.5,1);const mat=color=>new THREE.MeshStandardMaterial({color,roughness:.56,metalness:.18});this.gold=mat('#f6d46d');this.hair=mat('#442342');this.dark=mat('#302557');this.white=mat('#f4f5e5');this.colors=SPECTRUM.map(mat);this.glow=new THREE.MeshBasicMaterial({color:'#fff0b9',toneMapped:false});this.makeArt();this.reset();}
 mesh(parent,geometry,material,position,scale=[1,1,1]){const m=new THREE.Mesh(geometry,material);m.position.set(...position);m.scale.set(...scale);m.castShadow=m.receiveShadow=true;parent.add(m);return m;}
 attach(bone,offset){const c=this.character,g=new THREE.Group();g.position.copy(c.world(bone)).add(new THREE.Vector3(...offset).multiplyScalar(this.styleScale));g.scale.setScalar(this.styleScale);this.root.add(g);this.root.updateWorldMatrix(true,true);c.nodes[bone].attach(g);return g;}
 feather(){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute([0,0,0,-.12,.22,.025,-.14,.7,0,0,1,-.015,.14,.7,0,.12,.22,.025,0,.5,.09],3));geo.setIndex([0,1,6,1,2,6,2,3,6,3,4,6,4,5,6,5,0,6,0,5,4,0,4,3,0,3,2,0,2,1]);geo.computeVertexNormals();return geo;}
 segment(parent,a,b,radius,material){const from=new THREE.Vector3(...a),to=new THREE.Vector3(...b),delta=to.clone().sub(from),mesh=this.mesh(parent,new THREE.CylinderGeometry(radius*.6,radius,delta.length(),6),material,from.clone().lerp(to,.5).toArray());mesh.quaternion.setFromUnitVectors(Y,delta.normalize());return mesh;}
 makeArt(){const c=this.character,crest=this.featherGeometry=this.feather(),head=this.attach('B_Head',[0,.22,-.04]);for(let i=0;i<3;i++){const f=this.mesh(head,crest,this.colors[i],[.1+i*.04,.12,-.02],[.4,.28+i*.04,.4]);f.rotation.z=-.25-i*.18;}
  const chest=this.attach('B_Spine2',[0,-.05,.23]);this.mesh(chest,this.ball,this.gold,[0,0,0],[.15,.18,.055]);this.mesh(chest,this.ball,this.glow,[0,.01,.025],[.075,.09,.04]);
  const belt=this.attach('B_Pelvis',[0,-.1,-.18]);for(let i=0;i<5;i++){const f=this.mesh(belt,crest,this.colors[i+1],[(i-2)*.045,-.04,0],[.45,.36,.45]);f.rotation.z=Math.PI+(i-2)*.12;this.tails.push(f);}
  const back=this.attach('B_Spine2',[0,-.1,-.26]);for(const sign of[-1,1]){const wing=new THREE.Group();wing.position.set(sign*.2,0,0);back.add(wing);const outer=new THREE.Group();outer.position.set(sign*1.2,.08,-.05);wing.add(outer);this.segment(wing,[0,0,0],[sign*.6,.12,-.04],.085,this.colors[0]);this.segment(wing,[sign*.6,.12,-.04],[sign*1.2,.08,-.05],.065,this.colors[1]);for(let i=0;i<10;i++){const f=this.mesh(outer,crest,this.colors[i<3?2:i<6?3:i<8?4:5],[sign*(i*.095),.1-i*.045,.02-i*.012],[1.35,1.15+i*.035,1]);f.rotation.z=-sign*(Math.PI*.60-i*.04);this.feathers.push(f);}for(let i=0;i<7;i++){const f=this.mesh(wing,crest,this.colors[i<3?0:i<5?1:2],[sign*(.1+i*.14),-.06,.1],[1.2,.7+i*.035,1]);f.rotation.z=-sign*(Math.PI*.85-i*.05);}this.wings.push({wing,outer,sign});}
  this.wand=this.attach('B_R_Hand',[0,0,0]);this.mesh(this.wand,new THREE.CylinderGeometry(.027,.035,.8,7),this.gold,[0,.35,0]);this.mesh(this.wand,this.ball,this.dark,[0,0,0],[.085,.2,.085]);this.star=new THREE.Group();this.star.position.y=.84;this.wand.add(this.star);for(let i=0;i<7;i++){const a=i*Math.PI*2/7,f=this.mesh(this.star,new THREE.ConeGeometry(.065,.23,4),this.colors[i],[Math.sin(a)*.15,Math.cos(a)*.15,0]);f.rotation.z=-a;}this.mesh(this.star,this.ball,this.glow,[0,0,0],[.14,.14,.14]);this.tip=new THREE.Object3D();this.tip.position.y=1.03;this.wand.add(this.tip);
 }
 reset(){this.base.reset();this.flap=0;this.pose(0,0,new THREE.Vector3(),null,false);}
 pose(dt,time,velocity,target,casting){const c=this.character;c.update('Idle',dt);for(let i=0;i<c.bones.length;i++){c.bones[i].position.copy(c.rest[i].p);c.bones[i].quaternion.copy(c.rest[i].q);}const speed=velocity.length(),glide=Math.min(1,speed/16),lean=.08+glide*.18;c.nodes.B_Spine.rotation.x+=lean;c.nodes.B_Spine1.rotation.x+=lean*.3;c.nodes.B_L_Thigh.rotation.x+=.12+glide*.35;c.nodes.B_R_Thigh.rotation.x+=.05+glide*.32;c.nodes.B_L_Calf.rotation.x+=.25+Math.sin(time*2.4)*.07;c.nodes.B_R_Calf.rotation.x+=.4+Math.sin(time*2.4+1)*.08;this.root.updateWorldMatrix(true,true);
  const neutral=this.root.localToWorld(new THREE.Vector3(-.4,1.25,.3).multiplyScalar(this.styleScale));this.base.arm('L',neutral,dt);const right=target&&casting?target:this.root.localToWorld(new THREE.Vector3(.48,1.5,.36).multiplyScalar(this.styleScale));this.base.arm('R',right,dt);this.root.updateWorldMatrix(true,true);const hand=c.hand('R'),direction=casting&&target?target.clone().sub(hand).normalize():new THREE.Vector3(.2,.9,.35).transformDirection(this.root.matrixWorld);const q=new THREE.Quaternion().setFromUnitVectors(Y,direction);this.wand.quaternion.copy(this.wand.parent.getWorldQuaternion(new THREE.Quaternion()).invert()).multiply(q);
  this.flap=Math.sin(time*(glide>.7?4:7));for(const {wing,outer,sign}of this.wings){wing.rotation.y=sign*(.12+this.flap*(.22-glide*.10));wing.rotation.z=sign*(.05+this.flap*(.33-glide*.13));outer.rotation.y=sign*(.15+Math.sin(time*7-.8)*.14*(1-glide*.5));outer.rotation.z=sign*(.08+this.flap*.08);}for(let i=0;i<this.tails.length;i++)this.tails[i].rotation.x=Math.sin(time*4+i*.45)*.12;this.star.rotation.y=time*2;this.base.sync(time);this.root.updateWorldMatrix(true,true);
 }
 muzzle(){return this.tip.getWorldPosition(new THREE.Vector3());}
 diagnostics(){return{...this.character.diagnostics(),bodyHeight:FEMALE_HERO_BODY.height,bodyModel:this.character.metadata.source,bodyStyle:'Solara complete fitted model / Rainbow Star style',solaraFeatures:this.base.parts.length,wings:this.wings.length,feathers:this.feathers.length+14,flap:this.flap,wand:this.muzzle().toArray(),rightHand:this.character.hand('R').toArray()};}
}
